              {t.ceoView}
            </button>
          </nav>

          <div className="flex items-center gap-1 bg-slate-100 p-1 rounded-lg">
            <button 
              onClick={() => setLang('de')}
              className={`w-8 h-8 flex items-center justify-center rounded-md text-[10px] font-black uppercase transition-all ${lang === 'de' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}
            >
              DE
            </button>
            <button 
              onClick={() => setLang('en')}
              className={`w-8 h-8 flex items-center justify-center rounded-md text-[10px] font-black uppercase transition-all ${lang === 'en' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}
            >
              EN
            </button>
          </div>
        </div>
