      const defaults: Question[] = [
        { 
          id: 'q-1', 
          text: 'Wie sicher fühlen Sie sich mit der aktuellen Absturzsicherung und dem Gerüstaufbau auf dieser Baustelle?', 
          type: QuestionType.SATISFACTION_SCALE, 
          hidden: false, 
          isRecurring: true, 
          activeYears: [], 
          activeMonths: [] 
        },
        { 
          id: 'q-2', 
          text: 'Bewerten Sie die Qualität und Präzision der gelieferten Hölzer/Binder für diesen Rahmen.', 
          type: QuestionType.PERFORMANCE_RATING, 
          hidden: false, 
          isRecurring: true, 
          activeYears: [], 
          activeMonths: [] 
        },
        { 
          id: 'q-3', 
          text: 'Beschreiben Sie spezifische Baustellenrisiken (lose Ziegel, Oberleitungen usw.), die aufgetreten sind.', 
          type: QuestionType.TEXT_FEEDBACK, 
          hidden: false, 
          isRecurring: true, 
          activeYears: [], 
          activeMonths: [] 
        }
      ];
      setQuestions(defaults);
      localStorage.setItem('survey_questions', JSON.stringify(defaults));
    } else {
      setQuestions(JSON.parse(rawSaved));
    }
